def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    try:
        nanoseconds = int(nanoseconds)
        if tz is not None:
            tz = pytz.timezone(tz)
            value = datetime.datetime.fromtimestamp(nanoseconds / 1000000000, tz=tz)
