def extostr(e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """

    def _extostr(e, level, path):
        if level > max_level:
            return ""
        output = ""
        if isinstance(e, SyntaxError):
            output += "SyntaxError"
            if e.withtraceback:
                output += f" (Traceback)\n"
            output += f"  File {e.filename}, line {e.lineno}, in {e.name}\n"
            output += f"    {e.text}"
        elif isinstance(e, ImportError):
            output += "ImportError"
            if e.withtraceback:
                output += f" (Traceback)\n"
            output += f"  File {e.filename}, line {e.lineno}, in {e.name}\n"
            output += f"    {e.text}"
        else:
            output += f"{e.__class__.__name__}: {e}\n"
        if e.__cause__ is not None:
            output += _extostr(e.__cause__, level + 1, path + 1)
        if e.__context__ is not None:
            output += _extostr(e.__context__, level + 1, path + 1)
        if len(path) > max_path_level:
            output += " ...\n"
        return output

    return _extostr(e, 1, 0)

def append_text_to_file(file_name, text_buffer, encoding, overwrite=False):
    if not overwrite and os.path.exists(file_name):
        raise FileExistsError("File already exists")

    try:
        with open(file_name, "wb") as f:
            f.write(text_buffer.encode(encoding))
    except OSError as e:
        print(f"Error when writing to file: {e}")
        return -1

    return len(text_buffer)

