def _update_context(self, context):
    # Update context with properites of this graph.
    # Distinguishes between value contexts and error contexts.
    # Fills in missing indices for error contexts.
    for prop in self:
        if prop.endswith("_error"):
            error_prop, error_field = prop.split("_")
            if error_prop in context.value:
                # Value context already exists.
                # Create error subcontext if not exists.
                if "error" not in context.value[error_prop]:
                    context.value[error_prop]["error"] = {}
                # Fill in misssing indices for error subcontext.
                for index, error in enumerate(context.error[error_prop]):
                    if str(index) not in context.value[error_prop]["error"]:
                        context.value[error_prop]["error"][index] = {}
                # Fill in error name for error subsubcontext.
                if "index" not in context.value[error_prop]["error"]:
                    context.value[error_prop]["error"]["index"] = error_field
            else:
                # Value context does not exist.
                # Create all necessary subcontexts.
                context.value[error_prop] = {}
                context.value[error_prop]["error"] = {}
                context.value[error_prop]["error"][error_field] = {}
                context.value[error_prop]["error"]["index"] = error_field
        else:
            # No error field. Just store value.
            context.value[prop] = eval("self." + prop)

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    if len(bins) != len(edges) - 1:
        raise ValueError("Dimension mismatch: len(bins) = %d, len(edges) = %d" % (len(bins), len(edges)))
    return sum(bin * (edges[i+1] - edges[i]) for i, bin in enumerate(bins))

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    bins = np.array(bins)
    edges = np.array(edges)
    if not bins.ndim == 1 or not edges.ndim == 1:
        raise ValueError("The dimension of bins and edges must be 1.")
    if not len(bins) == len(edges) - 1:
        raise ValueError("The length of bins must be equal to the length of edges minus 1.")
    return np.trapz(bins, edges)

