def difference(d1, d2, level=-1):
    """Return a dictionary with items from d1 not contained in d2.

    level sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in d1 and d2 but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    d1 and d2 remain unchanged. However, d1 or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument level.
    """
    diff = {}
    for k, v in d1.items():
        if k not in d2 or d2[k] != v:
            diff[k] = v
        elif isinstance(v, dict) and level != 0:
            diff[k] = difference(v, d2[k], level-1)
    return diff

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == 0:
        return d1
    elif level != -1:
        level -= 1

    result = {}
    for k, v in d1.items():
        if isinstance(v, dict) and isinstance(d2.get(k), dict):
            diff = difference(v, d2[k], level)
            if diff or level == -1:
                result[k] = diff
        elif k not in d2 or v != d2[k]:
            result[k] = v

    return result

def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        if self.xmin <= coord <= self.xmax and self.ymin <= coord <= self.ymax:
            self.histogram[coord] += weight

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, (tuple, list)) or len(coord) != len(self.histogram):
        raise ValueError("Coordinate must be a list of valid indices")
    if not isinstance(weight, (int, float)):
        raise TypeError("Weight must be a number")
    for i, c in enumerate(coord):
        if c < 0 or c >= self.histogram_size[i]:
            return
        self.histogram[c] += weight

def _get_resource_name_regex():
        """Build or return the regular expressions that are used to validate
        the name of the Krake resources.

        Returns:
            (re.Pattern): the compiled regular expressions, to validate
            the resource name.
        """
        if bool(self.name_regex):
            return self.name_regex
        else:
            name_regex = r"^[a-z0-9]([-a-z0-9]*[a-z0-9])?$"
        return re.compile(name_regex)

