        if isinstance(elem, dict):
            return _handle_dict(elem)
        elif isinstance(elem, list):
            return _handle_list(elem)
        else:
            return None

    def _handle_dict(d):
        new_dict = {}
        for k, v in d.items():
            new_dict[k] = _handle_elem(v)
        if first_level:
            # copy identifying fields from manifest file
            for k in ('name', 'version', 'kind', 'namespace', 'uid'):
                new_dict[k] = d.get(k)
        return new_dict

    def _handle_list(l):
        new_list = []
        for elem in l:
            new_list.append(_handle_elem(elem))
        return new_list

    return _handle_dict(manifest_dict)

