def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    for resource in app.spec.manifest:
        # For each resource in the manifest
        if resource.type not in app.spec.observer_schema:
            # Only generate a default observer schema if
            # one doesn't already exist for this resource type
            app.spec.observer_schema[resource.type] = {
                "resource_version": "0.0.0",
                "dependencies": {}
            }

            # Add the resource schema for this resource type
            app.spec.observer_schema[resource.type]["schema"] = {
                "type": "object",
                "properties": {}
            }

            # Create a schema for each status field in this resource
            for status_field in resource.status:
                app.spec.observer_schema[resource.type]["schema"]["properties"][status_field.name] = {
                    "type": status_field.type,
                    "description": status_field.description
                }

            # Create a schema for each spec field in this resource
            for spec_field in resource.spec:
                app.spec.observer_schema[resource.type]["schema"]["properties"][spec_field.name] = {
                    "type": spec_field.type,
                    "description": spec_field.description
                }

            # Create a schema for each schema field in this resource
            for schema_field in resource.schema:
                app.spec.observer_schema[resource.type]["schema"]["properties"][schema_field.name] = {
                    "type": schema_field.type,
                    "description": schema_field.description
                }

    app.spec.observer_schema.update(app.spec.custom_observer_schema)
    return app.spec.observer_schema

def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
	"""
	Convert the SQL query to use the out-style parameters instead of
	the in-style parameters.

	*sql* (:class:`str` or :class:`bytes`) is the SQL query.

	*params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
	contains the set of in-style parameters. It maps each parameter
	(:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
	is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
	If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
	*params* must be a :class:`~collections.abc.Sequence`.

	Returns a :class:`tuple` containing:

	-	The formatted SQL query (:class:`str` or :class:`bytes`).

	-	The set of converted out-style parameters (:class:`dict` or
		:class:`list`).
	"""

	if self.in_style == 'qmark':
		return self._format_qmark(sql, params)
	elif self.in_style == 'named':
		return self._format_named(sql, params)
	elif self.in_style == 'format':
		return self._format_format(sql, params)
	elif self.in_style == 'pyformat':
		return self._format_pyformat(sql, params)
	else:
		raise ValueError("Unknown parameter style: {!r}".format(self.in_style))

