def validate(self, inventory, extract_spec_version=False):

    if extract_spec_version:
        # If spec version is not available, then determine it from the inventory
        if not inventory.has_property("type") or inventory.type not in self.SPEC_VERSIONS:
            raise ValueError("Unable to determine specification version from 'inventory' value")
        spec_version = self.SPEC_VERSIONS[inventory.type]
    else:
        spec_version = self.spec_version

    # Validate the structure of the inventory against the spec_version
    for key in inventory.keys():
        if key not in self.ALLOWED_KEYS[spec_version]:
            raise ValueError(f"Invalid key '{key}' in inventory")

    # Validate the type of the inventory against the spec_version
