    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if isinstance(arg, BinaryExpression):
            if arg.op in {LogicalAnd, LogicalOr}:
                if arg.left.equals(arg.right):
                    new_args.append(arg.left)
                elif arg.right.negated and arg.right.equals(arg.left):
                    new_args.append(arg.right)
                else:
                    new_args.append(arg)
            else:
                new_args.append(arg)
        else:
            new_args.append(arg)
    return new_args

