def prepare_repository_from_archive(archive_path: str, filename: Optional[str] = None, tmp_path: Union[PosixPath, str] = "/tmp") -> str:
    """Given an existing archive_path, uncompress it. Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """

    # Create a temporary file name if none provided
    if filename is None:
        filename = tmp_path / Path(archive_path).stem

    # Ensure the parent directory for the temporary file exists
    if not tmp_path.is_dir():
        tmp_path.mkdir(parents=True)

    # Remove any existing content if it already exists
    try:
        if filename.exists():
            filename.unlink()
    except:
        pass

    # Extract the archive
    try:
        subprocess.run(['tar', '-xvf', archive_path, '-C', str(filename)])
    except:
        raise Exception("Failed to untar archive")

    return str(Path(filename))

