def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    """Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf) will return a set of all roots of the
    sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of RDFS.subClassOf
    or SKOS.broader
    """
    if roots is None:
        roots = set()
    for subject, object_ in graph.subject_objects(prop):
        if subject not in roots:
            roots.add(subject)
    for subject, object_ in graph.subject_objects(prop):
        if object_ in roots:
            roots.remove(object_)
    return roots

