    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # First, try to parse the document as JSON
    try:
        data = json.loads(document)
        if data and data['subject'] == 'https://diaspora.fedbox.id/'
            return data
    except json.JSONDecodeError:
        pass

    # If JSON parsing fails, try to parse as XRD
    try:
        parser = etree.XMLParser(recover=True)
        root = etree.fromstring(document, parser)
        for key in root:
            if key.tag == 'Link' and key.attrib['rel'] == 'lrdd':
                return {
                    "subject": root.attrib['subject'],
                    "links": [
                        {
                            "rel": link.attrib['rel'],
                            "type": link.attrib['type'],
                            "href": link.attrib['href'],
                        }
                        for link in key
                    ]
                }
    except etree.XMLSyntaxError:
        pass

    # If both parsing attempts fail, return an empty dict
    return {}

